contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough balance for deposit");

        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        c.Put{value: depositAmount}(0);

        uint afterPutC = address(c).balance;
        uint afterPutThis = address(this).balance;

        require(afterPutC == beforeC + depositAmount, "deposit not credited to c");

        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        uint afterCollectC = address(c).balance;
        uint afterCollectThis = address(this).balance;

        if (collectReverted) {
            assert(afterCollectC == afterPutC && afterCollectThis == afterPutThis);
        } else {
            assert(afterCollectC + collectAmount <= afterPutC);
            assert(afterCollectThis >= afterPutThis + collectAmount);
        }
    }

    receive() external payable {}
}

