contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint putAmount, uint unlockTime, uint am) public payable {
        require(address(this).balance >= putAmount, "insufficient balance");
        c.Put{value: putAmount}(unlockTime);
        uint balBefore = c.Acc(address(this)).balance;
        uint before = address(c).balance;

        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

