            !reverted &&
            (eligible
                ? (afterBalance + collectAmount == beforeBalance &&
                   afterContractBalance + collectAmount == beforeContractBalance &&
                   address(this).balance + collectAmount >= amount)
                : (afterBalance == beforeBalance &&
                   afterContractBalance == beforeContractBalance))
